import 'package:flutter/material.dart';
import '../gateway/engine_gateway.dart';
import '../generated/torca_contract.dart';

class PairingScreen extends StatefulWidget { const PairingScreen({required this.gateway, super.key}); final EngineGateway gateway; @override State<PairingScreen> createState() => _PairingScreenState(); }
class _PairingScreenState extends State<PairingScreen> { final controller = TextEditingController(text: 'TORCA1'); String? error; @override void dispose() { controller.dispose(); super.dispose(); } @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Pair contact')), body: Padding(padding: const EdgeInsets.all(24), child: Column(children: [TextField(controller: controller, decoration: const InputDecoration(labelText: 'Pairing code')), if (error != null) Text(error!, style: TextStyle(color: Theme.of(context).colorScheme.error)), const SizedBox(height: 16), FilledButton(onPressed: () async { final id = DateTime.now().microsecondsSinceEpoch.toRadixString(16).padLeft(32, '0').substring(0, 32); final result = await widget.gateway.execute(StartPairingCommandDto(sessionIdHex: id, code: controller.text, expiresAtMs: DateTime.now().add(const Duration(minutes: 5)).millisecondsSinceEpoch)); if (!mounted) return; if (result.ok) { Navigator.of(context).pop(); } else { setState(() => error = result.error); } }, child: const Text('Start pairing'))]))); }
